fn selected(g: &ModelGraph, path: &[serde_json::Value]) -> Atom {
    let mut a = g.root.clone();
    for key in path {
        let id = reference(&a);
        a = if let Node::Map { .. } = &g.nodes[id as usize] {
            mapped(g, id, key.as_str().unwrap())
        } else {
            field(
                g,
                id,
                &key.as_str()
                    .map(str::to_owned)
                    .unwrap_or_else(|| key.as_u64().unwrap().to_string()),
            )
            .clone()
        };
    }
    a
}
fn argument(g: &mut ModelGraph, v: &serde_json::Value) -> Atom {
    use serde_json::Value as J;
    match v {
        J::Null => Atom::Null,
        J::Bool(b) => Atom::Bool(*b),
        J::Number(n) => Atom::Number(n.as_f64().unwrap()),
        J::String(s) => string(g, s),
        J::Array(values) => {
            let atoms = values.iter().map(|v| argument(g, v)).collect();
            Atom::Ref(push_array(g, atoms))
        }
        J::Object(fields) => {
            if let Some(fields) = fields.get("$record") {
                let id = push_object(g, vec![]);
                for field in fields.as_array().unwrap() {
                    let value = argument(g, &field[1]);
                    property(g, id, field[0].as_str().unwrap(), value);
                }
                return Atom::Ref(id);
            }
            if let Some(entries) = fields.get("$map") {
                let mut values = vec![];
                for entry in entries.as_array().unwrap() {
                    let key = argument(g, &entry[0]);
                    let value = argument(g, &entry[1]);
                    values.push((key, value));
                }
                let id = g.nodes.len() as u32;
                g.nodes.push(Node::Map {
                    entries: values,
                    properties: vec![],
                });
                return Atom::Ref(id);
            }
            if fields.get("$borrowed").is_some() {
                let properties = g.nodes[root(g) as usize].properties().to_vec();
                let id = g.nodes.len() as u32;
                g.nodes.push(Node::Object { properties });
                for method in Railroad.model_schema().methods {
                    property(g, id, method.name, Atom::BuiltinFunction(method.id.0));
                }
                return Atom::Ref(id);
            }
            if fields.get("$undefined").is_some() {
                return Atom::Undefined;
            }
            if let Some(value) = fields.get("$date") {
                let a = argument(g, value);
                let milliseconds = match a {
                    Atom::Number(n) => {
                        if n.is_finite() && n.abs() <= 8.64e15 {
                            if n == 0. {
                                0.
                            } else {
                                n.trunc()
                            }
                        } else {
                            f64::NAN
                        }
                    }
                    _ => panic!("date argument"),
                };
                let id = g.nodes.len() as u32;
                g.nodes.push(Node::Date {
                    milliseconds,
                    properties: vec![],
                });
                return Atom::Ref(id);
            }
            if let Some(name) = fields.get("$method") {
                let schema = Railroad.model_schema();
                return Atom::BuiltinFunction(
                    schema
                        .methods
                        .iter()
                        .find(|m| m.name == name.as_str().unwrap())
                        .unwrap()
                        .id
                        .0,
                );
            }
            if let Some(units) = fields.get("$utf16") {
                let id = g.strings.len() as u32;
                g.strings.push(JsString(
                    units
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(|n| n.as_u64().unwrap() as u16)
                        .collect(),
                ));
                return Atom::String(id);
            }
            if let Some(p) = fields.get("$node") {
                return selected(g, p.as_array().unwrap());
            }
            if let Some(n) = fields.get("$number") {
                return Atom::Number(f64::from_bits(
                    u64::from_str_radix(n.as_str().unwrap(), 16).unwrap(),
                ));
            }
            let id = push_object(g, vec![]);
            for (k, v) in fields {
                let a = argument(g, v);
                property(g, id, k, a)
            }
            Atom::Ref(id)
        }
    }
}
fn compare_graph(actual: J, expected: &J, label: &str) {
    fn first(a: &J, b: &J, path: String) -> Option<String> {
        if a == b {
            return None;
        }
        match (a, b) {
            (J::Array(a), J::Array(b)) if a.len() == b.len() => {
                for (i, (a, b)) in a.iter().zip(b).enumerate() {
                    if let Some(v) = first(a, b, format!("{path}/{i}")) {
                        return Some(v);
                    }
                }
            }
            (J::Object(a), J::Object(b)) if a.len() == b.len() => {
                for (k, a) in a {
                    if let Some(b) = b.get(k) {
                        if let Some(v) = first(a, b, format!("{path}/{k}")) {
                            return Some(v);
                        }
                    } else {
                        return Some(format!("{path}/{k}: missing expected field"));
                    }
                }
            }
            _ => {}
        }
        Some(format!(
            "{path}: {} versus {}",
            a.to_string().chars().take(160).collect::<String>(),
            b.to_string().chars().take(160).collect::<String>()
        ))
    }
    if let Some(diff) = first(&actual, expected, "$".into()) {
        panic!("{label}: {diff}")
    }
}
fn canonical(g: &ModelGraph, roots: &[Atom]) -> J {
    fn atom(g: &ModelGraph, a: &Atom, ids: &mut HashMap<u32, usize>, queue: &mut Vec<u32>) -> J {
        match a {
            Atom::Undefined => json!({"kind":"undefined"}),
            Atom::Null => json!({"kind":"null"}),
            Atom::Bool(v) => json!({"kind":"bool","value":v}),
            Atom::Number(n) => json!({"kind":"number","value":format!("{:016x}",n.to_bits())}),
            Atom::String(s) => json!({"kind":"string","value":g.strings[*s as usize].0}),
            Atom::BuiltinFunction(id) => json!({"kind":"function","value":id}),
            Atom::HostReference(_) => panic!("host capability is separate"),
            Atom::Ref(id) => {
                let next = queue.len();
                let index = *ids.entry(*id).or_insert_with(|| {
                    queue.push(*id);
                    next
                });
                json!({"kind":"ref","value":index})
            }
        }
    }
    let mut ids = HashMap::new();
    let mut queue = vec![];
    let roots = roots
        .iter()
        .map(|a| atom(g, a, &mut ids, &mut queue))
        .collect::<Vec<_>>();
    let mut nodes = vec![];
    let mut i = 0;
    while i < queue.len() {
        let node = &g.nodes[queue[i] as usize];
        let props=node.properties().iter().map(|p|json!({"key":g.strings[p.key as usize].0,"value":atom(g,&p.value,&mut ids,&mut queue),"flags":p.flags})).collect::<Vec<_>>();
        let mut out = json!({"kind":match node{Node::Error{..}=>"error",Node::Instance{..}=>"instance",Node::Object{..}=>"object",Node::Date{..}=>"date",Node::Array{..}=>"array",Node::Map{..}=>"map",Node::Set{..}=>"set"},"properties":props});
        match node {
            Node::Error { error_type, .. } => {
                out["errorType"] = serde_json::to_value(error_type).unwrap()
            }
            Node::Instance { .. } => out["prototype"] = "RailroadDb".into(),
            Node::Date { milliseconds, .. } => {
                out["milliseconds"] = format!("{:016x}", milliseconds.to_bits()).into()
            }
            Node::Array { length, .. } => out["length"] = (*length).into(),
            Node::Map { entries, .. } => {
                out["entries"] = entries
                    .iter()
                    .map(|(k, v)| {
                        json!([
                            atom(g, k, &mut ids, &mut queue),
                            atom(g, v, &mut ids, &mut queue)
                        ])
                    })
                    .collect()
            }
            Node::Set { values, .. } => {
                out["values"] = values
                    .iter()
                    .map(|v| atom(g, v, &mut ids, &mut queue))
                    .collect()
            }
            _ => {}
        }
        nodes.push(out);
        i += 1;
    }
    json!({"roots":roots,"nodes":nodes})
}
fn public_error(error: &PublicError) -> J {
    match error {
        PublicError::Pele(e) => {
            json!({"kind":"error","name":e.name,"message":e.message.encode_utf16().collect::<Vec<_>>(),"code":e.code,"type":e.diagram_type,"line":e.line,"column":e.column,"snippet":e.snippet})
        }
        PublicError::PeleUtf16(e) => {
            json!({"kind":"error","name":"PeleError","message":e.message.0,"code":e.code,"type":e.diagram_type.as_ref().map(|v|v.well_formed().unwrap()),"line":e.line,"column":e.column,"snippet":e.snippet.well_formed().unwrap()})
        }
        PublicError::JavaScript { name, message } => {
            json!({"kind":"error","name":name,"message":message.0})
        }
        other => panic!("unexpected capability {other:?}"),
    }
}
#[test]
fn all_pinned_railroad_native_method_alias_descriptor_and_svg_vectors() {
    let oracle: J = serde_json::from_str(ORACLE).unwrap();
    assert_eq!(
        oracle["revision"],
        "458322a5b8abb1ae57ddf127c32017ab9fb14a92"
    );
    let schema = Railroad.model_schema();
    assert_eq!(schema.methods.len(), 5);
    for item in oracle["methods"].as_array().unwrap() {
        let method = schema
            .methods
            .iter()
            .find(|m| m.name == item["name"].as_str().unwrap())
            .unwrap();
        assert_eq!(method.id.0 as u64, item["id"].as_u64().unwrap());
        assert_eq!(method.arity as u64, item["arity"].as_u64().unwrap());
    }
    let mut failures = vec![];
    for vector in oracle["vectors"].as_array().unwrap() {
        let result = std::panic::catch_unwind(|| {
            let name = vector["name"].as_str().unwrap();
            let mut doc = parsed(vector["source"].as_str().unwrap());
            let graph = doc.snapshot().unwrap();
            assert_eq!(
                canonical(&graph, &[graph.root.clone()]),
                vector["initial"],
                "{name} initial"
            );
            for (step_index, step) in vector["steps"].as_array().unwrap().iter().enumerate() {
                let entry = &step["entry"];
                let mut graph = doc.snapshot().unwrap();
                if let Some(edit) = entry.get("edit") {
                    let target = argument(&mut graph, &edit["target"]);
                    let value = argument(&mut graph, &edit["value"]);
                    let id = reference(&target);
                    let key = edit["key"].as_str().unwrap();
                    property(&mut graph, id, key, value.clone());
                    if let Node::Array { length, .. } = &mut graph.nodes[id as usize] {
                        if key == "length" {
                            if let Atom::Number(n) = value {
                                *length = n as u32;
                            }
                        } else if let Ok(index) = key.parse::<u32>() {
                            if index.to_string() == key && index < u32::MAX {
                                *length = (*length).max(index + 1);
                            }
                        }
                    }
                    for p in graph.nodes[id as usize].properties_mut() {
                        if graph.strings[p.key as usize].is(key) {
                            p.flags = edit["flags"].as_u64().unwrap_or(0) as u8;
                        }
                    }
                }
                let args = entry["args"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| argument(&mut graph, v))
                    .collect::<Vec<_>>();
                let receiver = entry
                    .get("receiver")
                    .map_or(graph.root.clone(), |v| argument(&mut graph, v));
                doc.apply(doc.revision(), graph).unwrap();
                let method = schema
                    .methods
                    .iter()
                    .find(|m| m.name == entry["method"].as_str().unwrap())
                    .unwrap()
                    .id;
                let outcome = doc
                    .invoke(
                        doc.revision(),
                        MethodCall {
                            method,
                            receiver: receiver.clone(),
                            arguments: args.clone(),
                        },
                        &mut Host,
                    )
                    .unwrap();
                let result = outcome
                    .result
                    .as_ref()
                    .map_or_else(public_error, |_| json!({"kind":"value"}));
                assert_eq!(
                    result, step["result"],
                    "{name}/{step_index} method {}",
                    entry["method"]
                );
                let mut roots = vec![outcome.graph.root.clone(), receiver];
                roots.extend(args);
                roots.push(outcome.result.unwrap_or(Atom::Undefined));
                compare_graph(
                    canonical(&outcome.graph, &roots),
                    &step["after"],
                    &format!("{name}/{step_index} after"),
                );
                if step["rendering"].get("gap").is_none() {
                    let mut options: RenderOptions =
                        serde_json::from_value(vector.get("options").cloned().unwrap_or(json!({})))
                            .unwrap();
                    options.render.now = Some(NOW);
                    let mut measured = Measured {
                        fixed: step["rendering"].get("measureTrace").is_some(),
                        trace: vec![],
                    };
                    let outcome = doc
                        .render_operation(doc.revision(), &options, &mut measured)
                        .unwrap();
                    let mut actual = match outcome.result {
                        Ok(r) => {
                            json!({"width":r.rendered.width,"height":r.rendered.height,"svgSha256":format!("{:x}",Sha256::digest(r.rendered.svg.as_bytes()))})
                        }
                        Err(e) => {
                            let mut e = public_error(&e);
                            e.as_object_mut().unwrap().remove("kind");
                            json!({"error":e})
                        }
                    };
                    if measured.fixed {
                        actual["measureTrace"] = json!(measured.trace);
                    }
                    let mut expected = step["rendering"].clone();
                    if expected.get("error").is_none() {
                        for key in ["width", "height"] {
                            expected[key] = json!(expected[key].as_f64().unwrap());
                        }
                    }
                    assert_eq!(actual, expected, "{name}/{step_index} rendering");
                    compare_graph(
                        canonical(&outcome.graph, &[outcome.graph.root.clone()]),
                        &step["renderedGraph"],
                        &format!("{name}/{step_index} render state"),
                    );
                }
            }
        });
        if result.is_err() {
            failures.push(vector["name"].clone());
        }
    }
    assert!(failures.is_empty(), "failed oracle vectors: {failures:?}");
}

fn project(g: &ModelGraph, a: &Atom, sets: bool) -> serde_json::Value {
    use serde_json::{json, Value as J};
    match a {
        Atom::Null | Atom::Undefined => J::Null,
        Atom::Bool(v) => json!(v),
        Atom::String(id) => g.strings[*id as usize]
            .well_formed()
            .map_or_else(|| json!({"$utf16":g.strings[*id as usize].0}), J::String),
        Atom::Number(n) => {
            // Historical model fixtures use JSON.stringify semantics. The graph
            // canonicalizer above separately checks exact IEEE payloads.
            if !n.is_finite() {
                J::Null
            } else if *n == 0. {
                json!(0)
            } else if n.fract() == 0. && *n >= 0. && *n < 18446744073709551616. {
                json!(*n as u64)
            } else if n.fract() == 0. && *n >= -9223372036854775808. && *n < 9223372036854775808. {
                json!(*n as i64)
            } else {
                json!(n)
            }
        }
        Atom::Ref(id) => match &g.nodes[*id as usize] {
            Node::Map { entries, .. } => entries
                .iter()
                .map(|(k, v)| json!([project(g, k, sets), project(g, v, sets)]))
                .collect(),
            Node::Set { values, .. } if sets => {
                values.iter().map(|v| project(g, v, sets)).collect()
            }
            Node::Set { .. } => json!({}),
            Node::Array { .. } => array(g, *id).iter().map(|v| project(g, v, sets)).collect(),
            node => {
                let mut out = serde_json::Map::new();
                for p in node.properties() {
                    if !matches!(p.value, Atom::Undefined) {
                        out.insert(
                            g.strings[p.key as usize].well_formed().unwrap(),
                            project(g, &p.value, sets),
                        );
                    }
                }
                J::Object(out)
            }
        },
        _ => panic!("source/method oracle projects data records only"),
    }
}
struct Resources {
    host: Json,
    metrics: MetricsResources,
}
impl RenderResources for Resources {
    fn text_width(&mut self, request: TextRequest<'_>) -> Result<f64, PeleError> {
        if self.host["measure"] == "fixed" {
            Ok(request.text.encode_utf16().count() as f64
                * request.size
                * if request.style & 1 != 0 { 0.71 } else { 0.6 })
        } else {
            self.metrics.text_width(request)
        }
    }
    fn parse_date(&mut self, input: &str) -> Result<Option<f64>, PeleError> {
        self.metrics.parse_date(input)
    }
    fn icon(&mut self, name: &str) -> Result<Option<TrustedSvg>, PeleError> {
        Ok(self.host["icons"][name]
            .as_str()
            .map(|s| TrustedSvg::from_trusted_markup(s.into())))
    }
}
#[test]
fn public_railroad_complete_historical_model_svg_error_corpus() {
    let fixture: Json =
        serde_json::from_str(include_str!("../../../fixtures/pele/railroad.json")).unwrap();
    let mut engine = PublicEngine::empty();
    engine.register(Railroad);
    let mut mismatches = Vec::new();
    for case in fixture["cases"].as_array().unwrap() {
        if std::env::var("RAILROAD_FILTER")
            .ok()
            .is_some_and(|filter| !case["id"].as_str().unwrap().contains(&filter))
        {
            continue;
        }
        if std::env::var("RAILROAD_SKIP_STRESS").is_ok()
            && case["id"].as_str().unwrap().starts_with("stress/")
        {
            continue;
        }
        let options: RenderOptions = serde_json::from_value(case["options"].clone()).unwrap();
        let source = case["source"].as_str().unwrap();
        let mut resources = Resources {
            host: case["host"].clone(),
            metrics: MetricsResources,
        };
        let mut model_projection = None;
        let actual = (|| -> Result<Json, PeleError> {
            let mut document = engine.parse(source, &options.parse)?;
            let graph = document.snapshot()?;
            let model = if case["host"]["modelProjection"] == "excluded" {
                None
            } else {
                let mut projection = project(&graph, &graph.root, false);
                projection.as_object_mut().unwrap().remove("byName");
                Some(projection)
            };
            model_projection = model.clone();
            let result = document.render(&options, &mut resources)?;
            roxmltree::Document::parse(&result.rendered.svg)
                .expect("successful SVG is well-formed XML");
            let mut result = serde_json::to_value(result).unwrap();
            if case["expected"]["result"].get("svgSha256").is_some() {
                use sha2::{Digest, Sha256};
                result["svgSha256"] = Json::String(format!(
                    "{:x}",
                    Sha256::digest(result["svg"].as_str().unwrap().as_bytes())
                ));
                result.as_object_mut().unwrap().remove("svg");
            }
            Ok(if let Some(model) = model {
                serde_json::json!({"model":model,"result":result})
            } else {
                serde_json::json!({"result":result})
            })
        })();
        let actual = match actual {
            Ok(v) => v,
            Err(e) => {
                if let Some(model) = model_projection {
                    serde_json::json!({"model":model,"error":e})
                } else {
                    serde_json::json!({"error":e})
                }
            }
        };
        if actual != case["expected"] {
            let differing = if actual.get("error").is_some()
                || case["expected"].get("error").is_some()
            {
                format!(
                    "actual error {} expected error {} modelEqual {}",
                    actual["error"],
                    case["expected"]["error"],
                    actual["model"] == case["expected"]["model"]
                )
            } else {
                let a = actual["result"]["svg"].as_str().unwrap_or("");
                let b = case["expected"]["result"]["svg"].as_str().unwrap_or("");
                let p = a
                    .bytes()
                    .zip(b.bytes())
                    .position(|(a, b)| a != b)
                    .unwrap_or(a.len().min(b.len()));
                format!(
                    "models actual {} expected {}\nSVG first diff byte {p}: actual {:?} expected {:?}",
                    actual["model"] == case["expected"]["model"],
                    actual["result"]["width"],
                    a.get(p.saturating_sub(40)..(p + 140).min(a.len())),
                    b.get(p.saturating_sub(40)..(p + 140).min(b.len()))
                )
            };
            mismatches.push(format!(
                "{} source {}\n{}",
                case["id"], case["source"], differing
            ));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} mismatches:\n{}",
        mismatches.len(),
        mismatches
            .into_iter()
            .take(200)
            .collect::<Vec<_>>()
            .join("\n\n")
    );
}
#[test]
fn railroad_registration_retention_resource_errors_and_recovery_without_reparse() {
    let count = Arc::new(AtomicUsize::new(0));
    let mut e = PublicEngine::empty();
    e.register(Counted(count.clone()));
    let mut doc = e.parse(SOURCE, &Default::default()).unwrap();
    e.register(Railroad);
    drop(e);
    let graph = doc.snapshot().unwrap();
    let mut options = RenderOptions::default();
    options.render.output_limit = Some(16);
    let outcome = doc
        .render_operation(doc.revision(), &options, &mut Host)
        .unwrap();
    assert!(matches!(
        outcome.result,
        Err(PublicError::Pele(PeleError {
            code: ErrorCode::Limit,
            ..
        }))
    ));
    assert_eq!(
        serde_json::to_string(&outcome.graph).unwrap(),
        serde_json::to_string(&graph).unwrap()
    );
    struct Broken;
    impl RenderResources for Broken {
        fn text_width(&mut self, _: TextRequest<'_>) -> Result<f64, PeleError> {
            Err(PeleError::new(
                "railroad host width failed",
                ErrorCode::Semantic,
            ))
        }
    }
    options.render.output_limit = None;
    let outcome = doc
        .render_operation(doc.revision(), &options, &mut Broken)
        .unwrap();
    assert!(
        matches!(outcome.result,Err(PublicError::Pele(PeleError{ref message,..}))if message=="railroad host width failed")
    );
    assert_eq!(
        serde_json::to_string(&outcome.graph).unwrap(),
        serde_json::to_string(&graph).unwrap()
    );
    assert!(doc
        .render_operation(doc.revision(), &options, &mut Host)
        .unwrap()
        .result
        .is_ok());
    assert_eq!(count.load(Ordering::SeqCst), 1);
    let rev = doc.revision();
    let snapshot = serde_json::to_string(&doc.snapshot().unwrap()).unwrap();
    let method_id = doc
        .model_schema()
        .methods
        .iter()
        .find(|m| m.name == "addRule")
        .unwrap()
        .id;
    let receiver = doc.snapshot().unwrap().root;
    assert!(doc
        .invoke(
            rev,
            MethodCall {
                method: method_id,
                receiver,
                arguments: vec![Atom::Ref(u32::MAX)]
            },
            &mut Host
        )
        .is_err());
    assert_eq!(doc.revision(), rev);
    assert_eq!(
        serde_json::to_string(&doc.snapshot().unwrap()).unwrap(),
        snapshot
    );
    assert!(doc.render_operation(rev - 1, &options, &mut Host).is_err());
    assert_eq!(doc.revision(), rev);
}
#[test]
fn railroad_graph_replacement_deep_cycles_utf16_and_borrowed_methods() {
    let mut doc = parsed(SOURCE);
    let mut g = doc.snapshot().unwrap();
    let r = root(&g);
    let mut previous = r;
    for _ in 0..6000 {
        previous = push_object(&mut g, vec![("next", Atom::Ref(previous))]);
    }
    let raw = g.strings.len() as u32;
    g.strings.push(JsString(vec![0xd800, 0xdc00, 0xd800]));
    property(&mut g, previous, "raw", Atom::String(raw));
    property(
        &mut g,
        previous,
        "nan",
        Atom::Number(f64::from_bits(0x7ff8000000000042)),
    );
    property(&mut g, r, "extra", Atom::Ref(previous));
    let json = serde_json::to_string(&g).unwrap();
    let g: ModelGraph = serde_json::from_str(&json).unwrap();
    doc.apply(doc.revision(), g).unwrap();
    let outcome = invoke(&mut doc, "setTitle", |g| vec![string(g, "")]);
    assert_eq!(reference(field(&outcome.graph, r, "extra")), previous);
    assert!(
        matches!(field(&outcome.graph,previous,"nan"),Atom::Number(n)if n.to_bits()==0x7ff8000000000042)
    );
    let mut g = outcome.graph;
    let borrowed = push_object(&mut g, vec![]);
    let arg = string(&mut g, "  borrowed  ");
    doc.apply(doc.revision(), g).unwrap();
    let method_id = doc
        .model_schema()
        .methods
        .iter()
        .find(|m| m.name == "setAccTitle")
        .unwrap()
        .id;
    let outcome = doc
        .invoke(
            doc.revision(),
            MethodCall {
                method: method_id,
                receiver: Atom::Ref(borrowed),
                arguments: vec![arg],
            },
            &mut Host,
        )
        .unwrap();
    assert!(outcome.result.is_ok());
    assert!(outcome
        .graph
        .text(field(&outcome.graph, borrowed, "accTitle"))
        .unwrap()
        .is("borrowed  "));
    let mut g = outcome.graph;
    let properties = g.nodes[r as usize].properties().to_vec();
    let replacement = g.nodes.len() as u32;
    g.nodes.push(Node::Instance {
        prototype: PrototypeId(1),
        properties,
    });
    g.root = Atom::Ref(replacement);
    let preserved = serde_json::to_string(&g).unwrap();
    doc.apply(doc.revision(), g).unwrap();
    assert_eq!(
        serde_json::to_string(&doc.snapshot().unwrap()).unwrap(),
        preserved
    );
    let outcome = invoke(&mut doc, "setTitle", |g| vec![string(g, "")]);
    assert!(outcome.result.is_ok());
    assert_eq!(reference(&outcome.graph.root), replacement);
}
#[test]
fn railroad_source_equivalent_builders_and_detached_private_lookup() {
    let source = "railroad-beta\nr = terminal(\"first\");";
    let mut doc = parsed(source);
    let args = apply_args(&mut doc, |g| {
        let definition = argument(
            g,
            &json!({"type":"sequence","elements":[
                {"type":"terminal","value":"n"},
                {"type":"repetition","element":{"type":"nonterminal","name":"r"},"min":1,"max":{"$number":"7ff0000000000000"}}
            ]}),
        );
        let name = string(g, "new");
        let rule = push_object(g, vec![("name", name), ("definition", definition)]);
        vec![Atom::Ref(rule)]
    });
    let result = method(&mut doc, "addRule", args);
    assert!(result.result.is_ok());
    same_source(
        &mut doc,
        &format!("{source}\nnew = sequence(terminal(\"n\"),oneOrMore(nonterminal(\"r\")));"),
    );
    let out = invoke(&mut doc, "getRule", |g| vec![string(g, "new")]);
    let rule = reference(out.result.as_ref().unwrap());
    let mut g = out.graph;
    let r = root(&g);
    assert_eq!(keys(&g, r).len(), 7);
    let empty = push_array(&mut g, vec![]);
    property(&mut g, r, "rules", Atom::Ref(empty));
    doc.apply(doc.revision(), g).unwrap();
    let out = invoke(&mut doc, "getRule", |g| vec![string(g, "new")]);
    assert_eq!(reference(out.result.as_ref().unwrap()), rule);
    same_source(&mut doc, "railroad-beta");
}
#[test]
fn railroad_deep_ir_and_active_cycle_refusal_preserve_graph_then_recover() {
    let mut doc = parsed("railroad-beta\nr = terminal(\"x\");");
    let mut g = doc.snapshot().unwrap();
    let r = root(&g);
    let rule = reference(&array(&g, reference(field(&g, r, "rules")))[0]);
    let original = field(&g, rule, "definition").clone();
    let mut last = original.clone();
    for _ in 0..1200 {
        let ty = string(&mut g, "optional");
        last = Atom::Ref(push_object(&mut g, vec![("type", ty), ("element", last)]));
    }
    property(&mut g, rule, "definition", last.clone());
    doc.apply(doc.revision(), g).unwrap();
    let deep = doc
        .render_operation(doc.revision(), &Default::default(), &mut Host)
        .unwrap();
    assert!(deep.result.is_ok());
    let mut g = deep.graph;
    let id = reference(&last);
    property(&mut g, id, "element", Atom::Ref(id));
    doc.apply(doc.revision(), g).unwrap();
    let refused = doc
        .render_operation(doc.revision(), &Default::default(), &mut Host)
        .unwrap();
    assert!(matches!(
        refused.result,
        Err(PublicError::Pele(PeleError {
            code: ErrorCode::Semantic,
            ..
        }))
    ));
    assert_eq!(reference(field(&refused.graph, id, "element")), id);
    let mut g = refused.graph;
    property(&mut g, rule, "definition", original);
    doc.apply(doc.revision(), g).unwrap();
    same_source(&mut doc, "railroad-beta\nr = terminal(\"x\");");
    let rule_out = invoke(&mut doc, "getRule", |g| vec![string(g, "r")]);
    assert_eq!(reference(rule_out.result.as_ref().unwrap()), rule);
}
